using System.Collections.Generic;
using UnityEngine;

namespace NivelCero
{
    /// <summary>
    /// Central effect player for both scenes. Clips are original WAVs generated by
    /// Tools/Audio/generate_audio.py and loaded from Resources/Audio. It limits
    /// simultaneous voices per sound, applies small pitch variation to avoid
    /// mechanical repetition and routes everything through the SFX volume.
    /// </summary>
    public sealed class SoundBank : MonoBehaviour
    {
        static SoundBank instance;
        readonly Dictionary<string, AudioClip> clips = new Dictionary<string, AudioClip>();
        readonly Dictionary<string, float> lastPlayed = new Dictionary<string, float>();
        readonly List<AudioSource> voices = new List<AudioSource>();
        readonly List<AudioSource> spatial = new List<AudioSource>();
        static readonly Dictionary<string, int> variants = new Dictionary<string, int>
        {
            { "step", 3 }, { "bit_chirp", 3 }, { "glitch_voice", 2 }
        };
        int roundRobin, spatialRobin;

        public static SoundBank Ensure()
        {
            if (instance != null) return instance;
            var go = new GameObject("Audio · banco de efectos");
            instance = go.AddComponent<SoundBank>();
            for (int i = 0; i < 18; i++)
            {
                var source = go.AddComponent<AudioSource>();
                source.playOnAwake = false; source.spatialBlend = 0; source.ignoreListenerPause = true;
                instance.voices.Add(source);
            }
            for (int i = 0; i < 12; i++)
            {
                var child = new GameObject("Voz espacial " + i);
                child.transform.SetParent(go.transform, false);
                var source = child.AddComponent<AudioSource>();
                source.playOnAwake = false; source.spatialBlend = 1; source.rolloffMode = AudioRolloffMode.Logarithmic;
                source.minDistance = 3; source.maxDistance = 40; source.dopplerLevel = 0; source.spread = 30;
                instance.spatial.Add(source);
            }
            GameSettings.Apply();
            return instance;
        }

        public static AudioClip Clip(string id)
        {
            var bank = Ensure();
            int count;
            string resolved = variants.TryGetValue(id, out count) ? id + "_" + Random.Range(0, count) : id;
            AudioClip clip;
            if (!bank.clips.TryGetValue(resolved, out clip))
            {
                clip = Resources.Load<AudioClip>("Audio/" + resolved);
                if (clip == null) Debug.LogWarning("Sonido no encontrado: " + resolved);
                bank.clips[resolved] = clip;
            }
            return clip;
        }

        /// <summary>Non-positional effect (UI, player feedback in 2D).</summary>
        public static void Play(string id, float volume = 1, float pitch = 1, float variation = .04f, float minInterval = .035f)
        {
            var bank = Ensure();
            if (!bank.Allowed(id, minInterval)) return;
            var clip = Clip(id); if (clip == null) return;
            var source = bank.NextVoice(bank.voices, ref bank.roundRobin);
            source.pitch = pitch * (1 + Random.Range(-variation, variation));
            source.PlayOneShot(clip, volume * GameSettings.Sfx);
        }

        /// <summary>3D-positioned effect with logarithmic falloff.</summary>
        public static void PlayAt(string id, Vector3 position, float volume = 1, float minDistance = 3, float maxDistance = 40, float variation = .04f, float minInterval = .035f)
        {
            var bank = Ensure();
            if (!bank.Allowed(id + "@" + Mathf.RoundToInt(position.x) + Mathf.RoundToInt(position.z), minInterval)) return;
            var clip = Clip(id); if (clip == null) return;
            var source = bank.NextVoice(bank.spatial, ref bank.spatialRobin);
            source.transform.position = position;
            source.minDistance = minDistance; source.maxDistance = maxDistance;
            source.pitch = 1 + Random.Range(-variation, variation);
            source.PlayOneShot(clip, volume * GameSettings.Sfx);
        }

        bool Allowed(string key, float minInterval)
        {
            float now = Time.unscaledTime, last;
            if (lastPlayed.TryGetValue(key, out last) && now - last < minInterval) return false;
            lastPlayed[key] = now; return true;
        }

        AudioSource NextVoice(List<AudioSource> pool, ref int robin)
        {
            for (int i = 0; i < pool.Count; i++)
            {
                var candidate = pool[(robin + i) % pool.Count];
                if (!candidate.isPlaying) { robin = (robin + i + 1) % pool.Count; return candidate; }
            }
            // Steal the oldest voice instead of stacking (prevents clipping).
            var stolen = pool[robin]; stolen.Stop(); robin = (robin + 1) % pool.Count; return stolen;
        }

        void OnDestroy() { if (instance == this) instance = null; }
    }
}
